import{_ as t}from"./chunks/daily-2026-08-20-report-attribution-figure-1.DYs6BrUv.js";import{_ as i,C as s,o as l,c as n,E as r,a2 as o}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"AI 团队同时交回三份报告，怎样保证验收没有串账？","description":"","frontmatter":{"title":"AI 团队同时交回三份报告，怎样保证验收没有串账？","date":"2026-08-20","column":"digital-employee","category":"daily","article_type":"project-research","edition":"research-center","research_question":"多 Agent 验收系统怎样证明每份报告属于哪个任务和哪次执行，而不是从正文里猜？","summary":"展示可以辅助挂树，验收必须核对唯一任务身份、执行轮次、版本替代与独立 QA。本文解释三字段门的有效边界、报告版本状态和错属工件的隔离策略。","item_id":"MANUAL-20260820-REPORT-ATTRIBUTION","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-20-report-attribution-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-fact-claim-matrices.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-experiment-run-log.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-independent-editorial-review-round4.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/03-independent-visual-package-review.md"]},"headers":[],"relativePath":"zh/digital-employee/2026-08-20-report-attribution.md","filePath":"zh/digital-employee/2026-08-20-report-attribution.md","lastUpdated":1787377515000}'),p={name:"zh/digital-employee/2026-08-20-report-attribution.md"};function d(c,e,h,u,b,m){const a=s("ArticleCover");return l(),n("div",null,[r(a,{image:"/assets/covers/daily-2026-08-20-report-attribution-cover.png",kicker:"数字员工 · 项目研究",title:"AI 团队同时交回三份报告，怎样保证验收没有串账？",summary:"展示可以辅助挂树，验收必须核对唯一任务身份、执行轮次、版本替代与独立 QA。",version:"MANUAL-20260820-REPORT-ATTRIBUTION",status:"Community Readability PASS · 2026-08-22",languageHref:"/en/digital-employee/2026-08-20-report-attribution",languageLabel:"English"}),e[0]||(e[0]=o(`<h1 id="ai-团队同时交回三份报告-怎样保证验收没有串账" tabindex="-1">AI 团队同时交回三份报告，怎样保证验收没有串账？ <a class="header-anchor" href="#ai-团队同时交回三份报告-怎样保证验收没有串账" aria-label="Permalink to &quot;AI 团队同时交回三份报告，怎样保证验收没有串账？&quot;">​</a></h1><p>开发、测试和运维三个 AI 智能体几乎同时交回报告。三份报告都说成功，系统也顺利生成“开发完成、测试通过、部署正常”的总结；但测试验收的是返工前版本，运维报告属于另一个任务，开发报告又写错了任务编号。系统没有漏掉任何文件，却拼出了一笔从未发生过的交付。</p><p>解决办法不是再让模型猜一次正文，而是把展示和验收分开：界面可以尽力帮助挂树，真正进入验收的报告必须拥有唯一、可验证的任务归属，并明确属于哪次执行。本文会给出身份门禁、报告版本状态和汇总检查清单；只要归属仍有歧义，系统就应停止，而不是替人猜一个最像的答案。</p><p>不熟悉任务归因的技术读者，可以先记住“归因三问”：</p><table tabindex="0"><thead><tr><th>归因问题</th><th>白话解释</th><th>可以检查什么</th></tr></thead><tbody><tr><td>谁干的</td><td>这份报告来自哪个项目、哪个任务、哪次执行</td><td>任务编号、父任务、项目根、运行系统记录的执行轮次</td></tr><tr><td>拿什么证明</td><td>报告中的成功结论有没有机器证据</td><td>实际命令、退出码、原始测试输出和当时的代码版本；只有真实采集过才能引用</td></tr><tr><td>对谁负责</td><td>哪份任务合同接收这组证据，谁有权验收</td><td>唯一任务绑定、报告替代关系、QA（独立质量验证）和最终接受决定</td></tr></tbody></table><p>这三问分别防止三类串账：把甲的报告记给乙、把模型写出的“测试通过”当成真实日志、让执行者自己宣布验收完成。当前 CodeFlowMu 只在部分关键路径实现了下文所述硬门；“所有权威元数据都由运行系统注入”仍是目标合同，不能冒充现成功能。</p><p>整条责任链可以先看成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务派发</span></span>
<span class="line"><span>  → 绑定任务与执行上下文</span></span>
<span class="line"><span>  → Agent（智能体）调用工具</span></span>
<span class="line"><span>  → 采集命令、退出码、测试与版本证据</span></span>
<span class="line"><span>  → 封装报告</span></span>
<span class="line"><span>  → 归因门核对任务、轮次与报告版本</span></span>
<span class="line"><span>  → 独立 QA 验证</span></span>
<span class="line"><span>  → 有权角色接受或拒绝</span></span></code></pre></div><p>其中“运行系统自动注入全部身份”和“统一采集全部工具证据”是目标方向；本文会明确指出哪些检查已经存在、哪些仍需实现。</p><h2 id="报告存在-不等于报告属于这项任务" tabindex="-1">报告存在，不等于报告属于这项任务 <a class="header-anchor" href="#报告存在-不等于报告属于这项任务" aria-label="Permalink to &quot;报告存在，不等于报告属于这项任务&quot;">​</a></h2><p>多 Agent（多智能体）系统常用四种简便办法归档报告：</p><ol><li>挂到同一聊天线程；</li><li>挂到最近创建的任务；</li><li>根据正文中出现的任务编号匹配；</li><li>根据发送角色匹配，例如 DEV（开发执行者）报告挂到最近的开发任务。</li></ol><p>这些办法适合帮助界面整理，却都不能单独支撑验收。</p><p>同一线程里可能连续出现两个根任务；返工报告会提到被驳回的旧任务；正文可能同时描述父任务与子任务；迟到的旧报告也可能在新任务创建后才被文件监听器发现。</p><p>如果系统在这些情况中“挑一个最像的”，它得到的只是概率较高的挂树，不是确定的证据归属。</p><h2 id="一份报告至少需要四张身份证" tabindex="-1">一份报告至少需要四张身份证 <a class="header-anchor" href="#一份报告至少需要四张身份证" aria-label="Permalink to &quot;一份报告至少需要四张身份证&quot;">​</a></h2><p>在 CodeFlowMu 的当前实现中，报告归属涉及四类信息：</p><table tabindex="0"><thead><tr><th>身份</th><th>作用</th><th>典型错误</th></tr></thead><tbody><tr><td>报告文件身份</td><td>表明报告本身是哪次回执</td><td>文件名序号与实际任务不符</td></tr><tr><td><code>task_id</code></td><td>声明直接工作所有者</td><td>仍指向返工前任务</td></tr><tr><td><code>parent_task_id</code></td><td>表明报告在任务树上的父节点</td><td>报告被挂到根任务而不是具体子任务</td></tr><tr><td><code>references</code></td><td>保存相关任务和历史引用</td><td>把“提到过”误当成“直接属于”</td></tr></tbody></table><p>这里最重要的区别是：<strong>直接所有者和相关引用不是一回事。</strong></p><p>假设开发 Agent 在 <code>TASK-042-REWORK-01</code> 上返工。报告可以在 <code>references</code> 中保留旧的 <code>TASK-042</code>，说明为什么返工；但直接 <code>task_id</code> 应指向当前返工任务。若系统只扫描引用，旧任务就可能“偷走”新报告。</p><h2 id="关键回执需要硬门-而不是相似度" tabindex="-1">关键回执需要硬门，而不是相似度 <a class="header-anchor" href="#关键回执需要硬门-而不是相似度" aria-label="Permalink to &quot;关键回执需要硬门，而不是相似度&quot;">​</a></h2><p>CodeFlowMu 为一个关键 DEV（开发执行者）回执场景实现了严格的三字段检查。<a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/pm/reportAttribution.ts" target="_blank" rel="noreferrer"><code>reportAttribution.ts</code></a> 会比较：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REPORT 文件名推断的 TASK 编号</span></span>
<span class="line"><span>        ==</span></span>
<span class="line"><span>frontmatter.task_id（文件头中的任务编号）</span></span>
<span class="line"><span>        ==</span></span>
<span class="line"><span>references[0]</span></span></code></pre></div><p>例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">filename</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">REPORT-20260820-042-DEV-to-PM.md</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">task_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TASK-20260820-042</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">references</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TASK-20260820-042</span></span></code></pre></div><p>三处一致，归因门才通过。若文件名是 <code>REPORT-...-043</code>，但 <code>task_id</code> 和引用仍是 <code>TASK-...-042</code>，系统会返回归因失败，而不是选择两个字段中的“多数”。缺少 <code>task_id</code> 或首个引用也会失败。</p><p>必须说明：这是 CodeFlowMu 当前某个关键 DEV 验收路径的应用级硬门，不是 FCoP（文件协作协议）对所有 REPORT（执行报告）、所有角色和所有文件名的普遍规则。FCoP 定义报告信封和引用能力；具体项目可以在宿主 Runtime（运行系统）中增加更严格的归因合同。</p><p>这道门只能排除“三处互相矛盾”，不能排除“三处一致地写错”。模型若复制了旧报告模板，可能在文件名、<code>task_id</code> 和首个引用中填入同一个旧任务，静态检查仍会通过。三字段一致因此是必要条件，不是任务归属的充分证明。</p><p>更强的目标设计是：智能体只提交报告正文和执行证据，权威元数据由运行系统根据当前会话注入。文件名、任务编号、父任务、执行轮次和逻辑序号不由模型自由书写；运行系统再把封包后的完整工件交给归因门复核。当前 CodeFlowMu 的三字段门已经能发现明显错配，但本文没有证据证明所有报告入口都统一采用了这种“运行系统封包”流程，所以这部分明确作为下一步合同，而不是现成功能。</p><p><img src="`+t+`" alt="任务身份与执行轮次绑定开发事实和 QA 验证；报告新旧由替代关系裁决，错属工件被隔离"></p><p><em>图 1：报告从身份、执行轮次、版本替代到 QA 验证的归属链。来源：本文根据 CodeFlowMu 固定提交与 W3C/OpenTelemetry 的身份传播边界整理。运行系统注入全部权威元数据仍是目标合同。</em></p><h2 id="哪些情况必须直接拒绝验收" tabindex="-1">哪些情况必须直接拒绝验收 <a class="header-anchor" href="#哪些情况必须直接拒绝验收" aria-label="Permalink to &quot;哪些情况必须直接拒绝验收&quot;">​</a></h2><p>归因门不仅要说明什么可以通过，还要给出 Veto List（否决清单）。“否决”表示证据当前不足或发生冲突，不等于认定提交者恶意欺诈：</p><ul><li>报告声明的代码版本与实际受测工作区不一致：判定为过期证据或版本冲突，隔离等待复核；</li><li>只写“测试通过”，却没有实际命令、退出码或原始输出：证据不足，不得进入成功总结；</li><li>文件名、任务编号和首个引用三处一致，却与运行系统的真实派工记录不符：归属失败；</li><li>同一任务存在多份报告，却没有执行轮次或明确的替代关系：不得自行选择“最新”文件；</li><li>只靠文件修改时间判断先后：不能证明因果顺序，必须结合事件序号、执行轮次或明确的替代记录；</li><li>若某条执行路径确实采用有时限的执行权，超过期限的报告只能进入复核；没有实现该机制的路径，不能虚构“租约过期”规则。</li></ul><p>这份清单把“看起来像成功”转换成可执行的停止条件：系统宁可返回“归属未确定”，也不能把三份真实报告拼成一笔虚假的交付。</p><h2 id="为什么需要身份传播-但不能把-trace-当验收" tabindex="-1">为什么需要身份传播，但不能把 Trace 当验收 <a class="header-anchor" href="#为什么需要身份传播-但不能把-trace-当验收" aria-label="Permalink to &quot;为什么需要身份传播，但不能把 Trace 当验收&quot;">​</a></h2><p>分布式系统已经遇到过类似问题。W3C 的 <a href="https://www.w3.org/TR/trace-context/" target="_blank" rel="noreferrer">Trace Context（链路追踪上下文）</a>用 <code>trace-id</code>（整条调用链编号）关联一条跨服务调用链；<code>parent-id</code>（上游操作编号）是调用方为当前请求携带的上游标识，接收方创建下游请求时会用新的当前操作标识继续传播。OpenTelemetry 的<a href="https://opentelemetry.io/docs/specs/otel/trace/api/" target="_blank" rel="noreferrer">追踪 API（编程接口）</a>规定每个 span（一次调用片段）最多有一个父片段，父子操作共享 TraceId（调用链编号），从而构成因果树。</p><p>这为 Agent 报告提供一个重要启发：任务身份和父关系必须随着工作传递，不能等报告回来以后再靠正文猜。</p><p>但类比到这里必须停止。Trace 能说明两次操作在同一调用链中，不证明输出内容正确；span 正常结束也不代表业务验收通过。Agent 报告同样需要把“关联到了哪个任务”和“是否满足任务合同”分开。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>身份关联正确</span></span>
<span class="line"><span>      ≠</span></span>
<span class="line"><span>报告内容真实</span></span>
<span class="line"><span>      ≠</span></span>
<span class="line"><span>测试角色已验证</span></span>
<span class="line"><span>      ≠</span></span>
<span class="line"><span>业务已经接受</span></span></code></pre></div><h2 id="展示挂树可以尽力-验收门禁不能猜" tabindex="-1">展示挂树可以尽力，验收门禁不能猜 <a class="header-anchor" href="#展示挂树可以尽力-验收门禁不能猜" aria-label="Permalink to &quot;展示挂树可以尽力，验收门禁不能猜&quot;">​</a></h2><p>CodeFlowMu 的 <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/ledger/reportParenting.ts" target="_blank" rel="noreferrer"><code>reportParenting.ts</code></a> 需要面对现实世界的不完整旧数据。它优先使用显式 <code>source_task_id</code> 或 <code>task_id</code>；缺失时，还会参考 <code>references</code>、文件名序号、正文重合和最近开放任务，帮助把报告展示在合理位置。</p><p>这种“最佳努力”对账本界面很有价值：历史数据不至于全部变成孤儿。</p><p>但如果把同一启发式直接用于自动验收，就会出现风险。正文相似可能因为两个任务都修改同一模块；最近任务可能只是刚好创建得晚；同一角色可能并行处理多个任务。</p><p>因此需要两条不同的结果：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>display_parent = best_effort_match(...)</span></span>
<span class="line"><span>acceptance_owner = deterministic_contract_or_undetermined(...)</span></span></code></pre></div><p>前者可以标记“推测挂载”并允许人工修正；后者只能返回明确唯一所有者，或者 <code>undetermined</code>。不确定不是系统失败，而是阻止串账的有效结果。</p><h2 id="同一线程出现两个根任务时-线程不能当父亲" tabindex="-1">同一线程出现两个根任务时，线程不能当父亲 <a class="header-anchor" href="#同一线程出现两个根任务时-线程不能当父亲" aria-label="Permalink to &quot;同一线程出现两个根任务时，线程不能当父亲&quot;">​</a></h2><p>真实协作中，一个聊天线程可能先处理缺陷 A，稍后又加入独立需求 B。若所有报告只带同一个 <code>thread_key</code>，旧的最终报告可能被新任务误用。</p><p>当前 <code>reportParenting.ts</code> 会在同一线程存在多个 ADMIN 根任务时按 lineage 和任务前缀分桶。只有引用或父链能唯一指向某个根时，报告才进入该桶；否则留在孤立区域，而不是挂到“线程中的第一个根任务”。</p><p>这条规则解决的是账本重建，不保证所有历史文件都能自动恢复。缺少身份的旧报告可能需要人工裁决。系统不应为了让界面更整齐而伪造确定性。</p><h2 id="同一任务交两次报告-必须明确哪一份有效" tabindex="-1">同一任务交两次报告，必须明确哪一份有效 <a class="header-anchor" href="#同一任务交两次报告-必须明确哪一份有效" aria-label="Permalink to &quot;同一任务交两次报告，必须明确哪一份有效&quot;">​</a></h2><p>任务编号相同，不代表两份报告可以互相覆盖。开发智能体第一次提交失败报告，修复后又提交成功报告时，系统至少需要执行轮次、报告自身身份、前一版本引用，以及明确的“替代了哪一份”关系。旧报告继续保留，但不再作为当前完成证据。</p><p>CodeFlowMu 当前账本已经识别 <code>submission_attempt</code>、<code>revision_of</code>、<code>supersedes</code> 和 <code>superseded_by</code> 等字段；汇总门也会排除标记为无效或已被替代的报告。这些是版本治理的可用零件，却不能证明每个报告入口都会自动递增执行轮次、并发提交一定得到唯一裁决。生产系统仍应把报告版本写成显式状态机：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>attempt-1 / report-v1 / failed</span></span>
<span class="line"><span>          └─ superseded_by → report-v2</span></span>
<span class="line"><span>attempt-2 / report-v2 / candidate</span></span>
<span class="line"><span>          └─ verified_by   → qa-report-v2</span></span></code></pre></div><p>覆盖原文件会抹掉失败历史；按“最新时间”自动获胜又会受时钟漂移影响。更稳妥的做法是用任务事件序号或执行轮次建立因果顺序，再由明确的替代关系决定哪份报告进入验收。</p><h2 id="报告归属通过以后-还不能生成最终总结" tabindex="-1">报告归属通过以后，还不能生成最终总结 <a class="header-anchor" href="#报告归属通过以后-还不能生成最终总结" aria-label="Permalink to &quot;报告归属通过以后，还不能生成最终总结&quot;">​</a></h2><p>即使开发报告已经正确挂到任务，项目经理也不能立刻宣布完成。CodeFlowMu 的 <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/pm/PmSummaryGate.ts" target="_blank" rel="noreferrer"><code>PmSummaryGate</code></a> 还会检查：</p><ul><li>下游子任务是否已经进入结算状态；</li><li>是否存在有效的 worker-to-PM 报告；</li><li>报告是否晚于对应任务创建；</li><li>产品任务是否具备要求的 QA 报告；</li><li>QA 是否给出 PASS；</li><li>需要浏览器验证时是否存在浏览器证据；</li><li>是否已经存在一份有效的最终总结。</li></ul><p>因此，“诊断列表为空”不能替代归因通过，“开发报告存在”不能替代 QA 通过，“PM 写了总结”也不能替代管理员或业务负责人的最终接受。</p><p>这正是 TMPA 中事实与接受分离的工程意义：执行者提交事实，验证者检查事实，有权角色决定是否接受。三者不能由同一份报告中的 <code>status: done</code> 合并。</p><p>这里还要收紧“晚于”的含义。当前汇总代码优先读取工件中的显式创建时间；部分兼容分支会参考账本时间或文件修改时间。Git 同步、解压、跨设备复制和本机时钟漂移都可能改变这些时间，因此物理时间只能作为辅助证据。涉及返工、重复提交和跨设备同步时，应优先比较由运行系统产生的事件序号、执行轮次和明确替代关系。</p><h2 id="_44-个测试覆盖了哪些串账路径" tabindex="-1">44 个测试覆盖了哪些串账路径 <a class="header-anchor" href="#_44-个测试覆盖了哪些串账路径" aria-label="Permalink to &quot;44 个测试覆盖了哪些串账路径&quot;">​</a></h2><p>本次写作在独立工作树固定 CodeFlowMu Open commit <code>ed5634c718b9e238c44bb70851020c9793546fe6</code>，重新运行报告挂树、归因和最终汇总测试，结果为 <strong>44/44 通过</strong>。</p><p>测试包含：</p><ul><li>文件名指向任务 003，而 <code>task_id</code> 与引用指向 002：拒绝；</li><li>缺少 <code>task_id</code> 或引用：拒绝；</li><li>三字段一致：通过；</li><li>返工报告显式指向当前任务，即使引用提到旧任务，也保持当前所有者；</li><li>同一线程两个根任务，旧 PM 最终报告不能挂到新根；</li><li>迟到报告早于子任务创建：不视为有效交付；</li><li>QA 报告缺失或 FAIL：阻止最终总结；</li><li>QA 未提供要求的浏览器证据：阻止总结；</li><li>diagnostics 为零但报告归因失败：整体验收仍失败。</li></ul><p>测试同时证明辅助挂树确实包含正文和最近任务回退。因此本文不会把 CodeFlowMu 描述成“所有历史报告都只靠三字段决定”。准确边界是：账本展示兼容不完整数据；关键验收路径使用更严格合同。</p><p>当前 44 项没有覆盖“三字段一致但共同指向错误任务”。该场景是根据门禁逻辑得到的反例，也是下一轮应新增的故障测试，不能写成已经通过的用例。</p><h2 id="六个值得复制的失败用例" tabindex="-1">六个值得复制的失败用例 <a class="header-anchor" href="#六个值得复制的失败用例" aria-label="Permalink to &quot;六个值得复制的失败用例&quot;">​</a></h2><h3 id="编号错配" tabindex="-1">编号错配 <a class="header-anchor" href="#编号错配" aria-label="Permalink to &quot;编号错配&quot;">​</a></h3><p>报告文件名、显式任务编号和首个引用中任意一处不同。期望：归因失败，保留原文件，不自动改名覆盖现场。</p><h3 id="三处一致地写错" tabindex="-1">三处一致地写错 <a class="header-anchor" href="#三处一致地写错" aria-label="Permalink to &quot;三处一致地写错&quot;">​</a></h3><p>从旧模板复制报告，让文件名、<code>task_id</code> 和首个引用都指向同一个错误任务。期望：若元数据不是由运行系统注入，就不能仅凭三字段一致进入验收；至少还要核对当前会话、执行轮次或签发上下文。</p><h3 id="旧报告迟到" tabindex="-1">旧报告迟到 <a class="header-anchor" href="#旧报告迟到" aria-label="Permalink to &quot;旧报告迟到&quot;">​</a></h3><p>报告创建时间早于目标子任务，却在监听器重启后才被发现。期望：可以展示为历史孤儿，不满足当前任务的有效报告条件。</p><h3 id="同一任务重复提交" tabindex="-1">同一任务重复提交 <a class="header-anchor" href="#同一任务重复提交" aria-label="Permalink to &quot;同一任务重复提交&quot;">​</a></h3><p>同一任务先后出现失败和成功报告。期望：保留两份工件，用执行轮次和 <code>supersedes</code> 关系选择候选；禁止覆盖旧文件，也禁止只按文件修改时间决定胜者。</p><h3 id="同线程多根" tabindex="-1">同线程多根 <a class="header-anchor" href="#同线程多根" aria-label="Permalink to &quot;同线程多根&quot;">​</a></h3><p>同一 <code>thread_key</code> 下存在两个独立根任务，报告只提供 thread。期望：<code>undetermined</code>，不得挂到第一个或最新根。</p><h3 id="qa-缺失或失败" tabindex="-1">QA 缺失或失败 <a class="header-anchor" href="#qa-缺失或失败" aria-label="Permalink to &quot;QA 缺失或失败&quot;">​</a></h3><p>开发报告正确、代码也存在，但必需 QA 报告缺失或 verdict 为 FAIL。期望：不生成成功总结，下游发布保持阻塞。</p><h2 id="报告创建与汇总清单" tabindex="-1">报告创建与汇总清单 <a class="header-anchor" href="#报告创建与汇总清单" aria-label="Permalink to &quot;报告创建与汇总清单&quot;">​</a></h2><p>报告创建时：</p><ol><li>在领取任务时就把任务身份、父任务和执行轮次放入运行上下文；</li><li>智能体只提交正文与证据，文件名和权威元数据由 Runtime 封包注入；</li><li>直接所有者放在固定字段，历史相关项放在引用列表；</li><li>记录发送角色、执行轮次、逻辑事件序号和创建时间；</li><li>对返工创建新尝试身份，用 <code>supersedes</code> 指向被替代报告，并保留旧任务引用。</li></ol><p>报告摄入时：</p><ol start="6"><li>先解析显式身份，再考虑辅助匹配；</li><li>多个候选同分时返回不确定，不随机选择；</li><li>保留原始文件、解析结果和冲突原因；</li><li>展示推测挂树时明确标注“未用于验收”。</li></ol><p>最终汇总前：</p><ol start="10"><li>优先用执行轮次、事件序号和替代关系核对报告新旧；物理时间只作辅助；</li><li>核对角色、任务所有者和必需证据；</li><li>QA 缺失、失败或证据不足时阻止成功总结；</li><li>把执行事实、验证裁决和业务接受保存为不同记录。</li></ol><h2 id="限制与待验证问题" tabindex="-1">限制与待验证问题 <a class="header-anchor" href="#限制与待验证问题" aria-label="Permalink to &quot;限制与待验证问题&quot;">​</a></h2><p>三字段一致可以排除一类明显串账，却不能证明报告正文真实，也不能阻止模型三处一致地引用错误任务。运行系统封包可以显著缩小这类错误面，但当前资料不足以证明所有 CodeFlowMu 报告入口都已执行该合同。</p><p>正文匹配算法也没有误挂率基准；本文不主张它适合验收。跨仓库、跨组织的任务身份还需要命名空间或全局身份，单纯日期和三位序号可能碰撞。</p><p>44 个测试来自第一方固定提交，不是外部审计。下一步应加入随机生成的任务树、三处一致但上下文错误、同任务多执行轮次、报告乱序、重复监听事件、时钟漂移和跨重启重建测试，量化 <code>undetermined</code>、误挂和漏挂比例。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>多 Agent 协作最危险的错误不一定是报告丢失，而是报告存在、内容也合理，却被算进了错误任务。</p><blockquote><p>展示系统可以努力帮人找到报告；验收系统没有权力在归属不清时替人猜。</p></blockquote><p>让任务身份和父关系随执行传递，让关键报告通过确定性归因门，让 QA 和最终接受继续保持独立。这样，三份报告才能形成三条可审查证据，而不是被拼成一笔看似完整的假交付。</p><h2 id="主要来源" tabindex="-1">主要来源 <a class="header-anchor" href="#主要来源" aria-label="Permalink to &quot;主要来源&quot;">​</a></h2><ol><li><a href="https://www.w3.org/TR/trace-context/" target="_blank" rel="noreferrer">W3C Trace Context</a></li><li><a href="https://opentelemetry.io/docs/specs/otel/trace/api/" target="_blank" rel="noreferrer">OpenTelemetry Tracing API</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.zh.md" target="_blank" rel="noreferrer">FCoP v3 中文规范，固定提交</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/pm/reportAttribution.ts" target="_blank" rel="noreferrer">CodeFlowMu reportAttribution 固定提交</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/ledger/reportParenting.ts" target="_blank" rel="noreferrer">CodeFlowMu reportParenting 固定提交</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/pm/PmSummaryGate.ts" target="_blank" rel="noreferrer">CodeFlowMu PmSummaryGate 固定提交</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/ledger/LedgerBuilder.ts" target="_blank" rel="noreferrer">CodeFlowMu LedgerBuilder 固定提交</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/ae27de71b1a8809c2bd69acedc1482570d55a322/docs/public/releases/tmpa/v1.0/artifacts/tmpa-core-specification-s1.0-zh.md" target="_blank" rel="noreferrer">TMPA 核心规范 S1.0，固定提交</a></li></ol><p>访问日期：2026-08-20。</p>`,99))])}const _=i(p,[["render",d]]);export{f as __pageData,_ as default};
